"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60082"],{86476(e){e.exports=JSON.parse('{"id":"F430","slug":"narrative-contagion-sir","name":"Narrative Contagion (SIR Model)","subject":"Behavioral Finance","section":"Behavioral","topic":"Narrative economics (Shiller)","level":"Intermediate","aliases":["narrative economics","Shiller epidemic of ideas","R0 of a story","spread of a rumor"],"formula":{"latex":"R_{0}=\\\\frac{\\\\beta}{\\\\gamma},\\\\quad i_{max}=1-\\\\frac{1+\\\\ln R_{0}}{R_{0}},\\\\quad z=1-e^{-R_{0}z}","also":[],"text":"Basic reproduction number R0 = contagion rate / forgetting (recovery) rate. If R0 > 1 the story spreads. Peak share actively spreading = 1 - (1 + ln R0) / R0; Share who ever hear and believe it, z, solves z = 1 - e^(-R0 x z). A story dies out if R0 is 1 or less"},"symbols":[{"symbol":"beta","meaning":"Rate at which each active believer passes the story on, per week","unit":"per week"},{"symbol":"gamma","meaning":"Rate at which people lose interest and stop spreading it, per week","unit":"per week"},{"symbol":"R0","meaning":"Average number of new believers per active believer at the start","unit":"number"}],"when_to_use":"Use it to think about how popular narratives, such as a boom story or a panic story, spread like an epidemic. The same mathematics as disease models gives the threshold for a story to take off and how many people it eventually reaches. Shiller argues such narratives drive markets. The parameters are not directly measured, so the model gives intuition about thresholds, not forecasts.","worked_example":{"problem":"A story spreads at 0.45 per week among active believers, and interest fades at 0.30 per week.","inputs":{"b":0.45,"g":0.3},"steps":[{"label":"R0 = contagion / fading","working":"0.45 / 0.3","value":"1.500"},{"label":"Peak share actively spreading = 1 - (1 + ln R0) / R0","working":"1-(1+ln(1.5)) / 1.5","value":"6.30%"},{"label":"Newton step 1 for the final share (start at 0.5)","working":"0.5-(0.5-1+exp(-1.5 x 0.5)) / (1-1.5 x exp(-1.5 x 0.5))","value":"0.59481"},{"label":"Newton step 2","working":"0.594814-(0.594814-1+exp(-1.5 x 0.594814)) / (1-1.5 x exp(-1.5 x 0.594814))","value":"0.582985"},{"label":"Newton step 3","working":"0.582985-(0.582985-1+exp(-1.5 x 0.582985)) / (1-1.5 x exp(-1.5 x 0.582985))","value":"0.582812"},{"label":"Newton step 4","working":"0.582812-(0.582812-1+exp(-1.5 x 0.582812)) / (1-1.5 x exp(-1.5 x 0.582812))","value":"0.582812"},{"label":"Final share who believe the story","working":"0.582812","value":"58.3%"},{"label":"Share who never hear it","working":"1-0.582812","value":"41.7%"}],"answer":"R0 is 1.500, above 1, so the story spreads. At its peak 6.30% of people are actively spreading it, and in the end 58.3% of the population will have heard and believed it. The share who never hear it is 41.7%."},"calculator":{"available":true,"inputs":[{"id":"b","label":"Contagion rate per week","unit":"","type":"number","default":0.45,"hint":""},{"id":"g","label":"Fading rate per week","unit":"","type":"number","default":0.3,"hint":""}],"checks":[{"expr":"b>0 and g>0 and b/g>1.0001","message":"Enter rates above zero with a contagion rate larger than the fading rate (R0 above 1)."}],"steps":[{"id":"r0","label":"R0 = contagion / fading","expr":"b/g","format":"num3"},{"id":"pk","label":"Peak share actively spreading = 1 - (1 + ln R0) / R0","expr":"1-(1+ln(r0))/r0","format":"pct2"},{"id":"z1","label":"Newton step 1 for the final share (start at 0.5)","expr":"0.5-(0.5-1+exp(-r0*0.5))/(1-r0*exp(-r0*0.5))","format":"num5"},{"id":"z2","label":"Newton step 2","expr":"z1-(z1-1+exp(-r0*z1))/(1-r0*exp(-r0*z1))","format":"num6"},{"id":"z3","label":"Newton step 3","expr":"z2-(z2-1+exp(-r0*z2))/(1-r0*exp(-r0*z2))","format":"num6"},{"id":"z4","label":"Newton step 4","expr":"z3-(z3-1+exp(-r0*z3))/(1-r0*exp(-r0*z3))","format":"num6"},{"id":"fin","label":"Final share who believe the story","expr":"z4","format":"pct1"},{"id":"never","label":"Share who never hear it","expr":"1-fin","format":"pct1"}],"results":["r0","pk","fin"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"r0":1.5,"pk":0.0630232612612237,"fin":0.5828116438658114,"never":0.4171883561341886}},"finder":{"finds":"Whether a narrative takes off and how far it spreads","needs":"Contagion and fading rates"},"related":[{"slug":"information-cascade-posterior","name":"Herding: Information Cascade Posterior"},{"slug":"investor-sentiment-composite","name":"Investor Sentiment Composite Index"},{"slug":"rational-bubble-growth","name":"Rational Bubble: Required Growth and Survival"}],"related_ids":["F422","F429","F428"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>R</mi><mn>0</mn></msub><mo>=</mo><mfrac><mi>\u03B2</mi><mi>\u03B3</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>i</mi><mrow><mi>m</mi><mi>a</mi><mi>x</mi></mrow></msub><mo>=</mo><mn>1</mn><mo>\u2212</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>ln</mi><mo>\u2061</mo><msub><mi>R</mi><mn>0</mn></msub></mrow><msub><mi>R</mi><mn>0</mn></msub></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>z</mi><mo>=</mo><mn>1</mn><mo>\u2212</mo><msup><mi>e</mi><mrow><mo>\u2212</mo><msub><mi>R</mi><mn>0</mn></msub><mi>z</mi></mrow></msup></mrow><annotation encoding=\\"application/x-tex\\">R_{0}=\\\\frac{\\\\beta}{\\\\gamma},\\\\quad i_{max}=1-\\\\frac{1+\\\\ln R_{0}}{R_{0}},\\\\quad z=1-e^{-R_{0}z}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"murabaha-implied-rate","name":"Murabaha Mark-Up and Implied Rate"},"next":{"slug":"neobank-unit-economics","name":"Neobank Unit Economics: Margin per Customer and Payback"},"lesson":null,"total":522}')}}]);